-- The application store's schema at version 31, exactly as the
-- Swift store's migrations leave it. Generated by
-- scripts/ios/dump-store-schema.sh; do not edit.

CREATE TABLE channel (
    id TEXT PRIMARY KEY NOT NULL,
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    canonical_name TEXT,
    name TEXT,
    alias TEXT,
    channel_id_hex TEXT NOT NULL,
    tint BLOB NOT NULL,
    key_digest TEXT NOT NULL,
    region_code BLOB,
    max_flood_hops INTEGER,
    joined_phone INTEGER NOT NULL DEFAULT 0,
    joined_device INTEGER NOT NULL DEFAULT 0,
    notifications_enabled INTEGER NOT NULL DEFAULT 0,
    created_at_ms INTEGER NOT NULL,
    joined_at_ms INTEGER,
    UNIQUE (owner_identity_id, key_digest)
);

CREATE TABLE channel_conversation (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    channel_id TEXT NOT NULL REFERENCES channel(id) ON DELETE CASCADE,
    conversation_address TEXT NOT NULL,
    draft_text TEXT NOT NULL DEFAULT '',
    created_at_ms INTEGER NOT NULL,
    last_read_at_ms INTEGER NOT NULL DEFAULT 0,
    UNIQUE (owner_identity_id, channel_id)
);

CREATE TABLE chat_applied_mutation (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    handle INTEGER NOT NULL,
    revision INTEGER NOT NULL,
    PRIMARY KEY (owner_identity_id, session_id, handle)
);

CREATE TABLE chat_delivery_fragment (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    handle INTEGER NOT NULL,
    fragment_index INTEGER NOT NULL,
    state TEXT NOT NULL, via_flood INTEGER NOT NULL DEFAULT 0, repeaters BLOB, anonymous_repeats INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (
        owner_identity_id, session_id, handle, fragment_index
    )
);

CREATE TABLE chat_message (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL,
    handle INTEGER NOT NULL,
    conversation_address TEXT NOT NULL,
    sender_address TEXT,
    direction INTEGER NOT NULL,
    message_type INTEGER,
    wire_id INTEGER,
    epoch INTEGER,
    client_token INTEGER,
    sender_handle TEXT,
    regarding_handle INTEGER,
    background_color BLOB,
    text_color BLOB,
    body TEXT NOT NULL,
    complete INTEGER,
    present_fragments INTEGER,
    fragment_count INTEGER,
    finalized INTEGER,
    delivery_state TEXT,
    deleted INTEGER NOT NULL DEFAULT 0,
    created_at_ms INTEGER NOT NULL, edited INTEGER NOT NULL DEFAULT 0, presence INTEGER NOT NULL DEFAULT 0, received_late INTEGER NOT NULL DEFAULT 0, delivered_late INTEGER NOT NULL DEFAULT 0, original_body TEXT, sender_hint BLOB, rx_rssi_dbm INTEGER, rx_snr_cb INTEGER, rx_lqi INTEGER, rx_hop_count INTEGER, rx_route_hints BLOB, rx_source_authenticated INTEGER, is_reaction INTEGER NOT NULL DEFAULT 0, regarding_wire_id INTEGER, regarding_direction INTEGER, regarding_sender_hint BLOB, regarding_target_session_id TEXT, regarding_target_handle INTEGER, delivery_session_id TEXT, delivery_handle INTEGER, delivered_flooded INTEGER NOT NULL DEFAULT 0, delivery_progress_at_ms INTEGER, silent INTEGER NOT NULL DEFAULT 0, regarding_unknown INTEGER NOT NULL DEFAULT 0, unknown_original INTEGER NOT NULL DEFAULT 0, forward_secret INTEGER,
    PRIMARY KEY (owner_identity_id, session_id, handle)
);

CREATE TABLE chat_outbound_archive (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    conversation_address TEXT NOT NULL,
    message_id INTEGER NOT NULL,
    fragment_index INTEGER NOT NULL,
    payload BLOB NOT NULL,
    PRIMARY KEY (
        owner_identity_id, conversation_address, message_id, fragment_index
    )
);

CREATE TABLE chat_stream_checkpoint (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    conversation_address TEXT NOT NULL,
    next_id INTEGER NOT NULL,
    epoch INTEGER NOT NULL,
    updated_at_ms INTEGER NOT NULL,
    PRIMARY KEY (owner_identity_id, conversation_address)
);

CREATE TABLE claimed_radio (
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    device_address TEXT NOT NULL,
    name TEXT,
    attached_at_ms INTEGER NOT NULL,
    PRIMARY KEY (owner_identity_id, device_address)
) WITHOUT ROWID;

CREATE TABLE direct_conversation (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    node_id INTEGER NOT NULL REFERENCES node(id) ON DELETE RESTRICT,
    draft_text TEXT NOT NULL DEFAULT '',
    created_at_ms INTEGER NOT NULL, last_read_at_ms INTEGER NOT NULL DEFAULT 0, notifications_enabled INTEGER NOT NULL DEFAULT 1,
    UNIQUE (owner_identity_id, node_id)
);

CREATE TABLE local_identity (
    id TEXT PRIMARY KEY NOT NULL,
    public_address TEXT NOT NULL UNIQUE,
    created_at_ms INTEGER NOT NULL
, advertised_name TEXT);

CREATE TABLE node (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_identity_id TEXT NOT NULL
        REFERENCES local_identity(id) ON DELETE CASCADE,
    public_address TEXT NOT NULL,
    alias TEXT,
    alias_search TEXT NOT NULL, advertised_name TEXT, system_role TEXT, radio_identifier TEXT, node_kind TEXT, advertisement BLOB, last_heard_at REAL, advertisement_authenticated INTEGER NOT NULL DEFAULT 0, is_saved INTEGER NOT NULL DEFAULT 0, is_favorite INTEGER NOT NULL DEFAULT 0, on_dev_identity INTEGER NOT NULL DEFAULT 0, notify_when_heard INTEGER NOT NULL DEFAULT 0, advertisement_received_at REAL,
    UNIQUE (owner_identity_id, public_address)
);

CREATE TABLE node_manual_route (
    node_id INTEGER PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    hints BLOB NOT NULL,
    hold_until_ms INTEGER NOT NULL,
    saved_latitude REAL,
    saved_longitude REAL,
    saved_accuracy REAL,
    prompt_settled INTEGER NOT NULL DEFAULT 0
, flood_hops INTEGER NOT NULL DEFAULT 1);

CREATE TABLE node_mgmt_card (
    node_id INTEGER PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    capabilities BLOB NOT NULL,
    device_version TEXT,
    device_model TEXT,
    device_name TEXT,
    fetched_at_ms INTEGER NOT NULL
);

CREATE TABLE node_peer_repeater_entry (
    node_id INTEGER NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    hint BLOB NOT NULL,
    position INTEGER NOT NULL,
    name TEXT,
    rssi_dbm INTEGER,
    snr_quarter_db INTEGER,
    last_heard_min INTEGER,
    latitude REAL,
    longitude REAL,
    location_precision INTEGER,
    region_codes BLOB,
    reported_at_ms INTEGER NOT NULL,
    PRIMARY KEY (node_id, hint)
) WITHOUT ROWID;

CREATE TABLE node_peer_repeaters (
    node_id INTEGER PRIMARY KEY REFERENCES node(id) ON DELETE CASCADE,
    total INTEGER,
    next_cursor BLOB,
    as_of_ms INTEGER NOT NULL
);

CREATE TABLE node_prop_cache (
    node_id INTEGER NOT NULL REFERENCES node(id) ON DELETE CASCADE,
    property_id INTEGER NOT NULL,
    value BLOB NOT NULL,
    fetched_at_ms INTEGER NOT NULL,
    PRIMARY KEY (node_id, property_id)
) WITHOUT ROWID;

CREATE INDEX channel_conversation_address_idx
    ON channel_conversation (owner_identity_id, conversation_address);

CREATE INDEX channel_owner_idx ON channel (owner_identity_id, id);

CREATE INDEX chat_message_conversation_idx
    ON chat_message (owner_identity_id, conversation_address, created_at_ms);

CREATE INDEX chat_message_delivery_idx ON chat_message (
    owner_identity_id, delivery_session_id, delivery_handle
);

CREATE INDEX chat_message_reaction_target_idx
    ON chat_message (
        owner_identity_id,
        regarding_target_session_id,
        regarding_target_handle
    )
    WHERE is_reaction = 1;

CREATE INDEX chat_message_wire_idx
    ON chat_message (owner_identity_id, conversation_address, direction, wire_id);

CREATE INDEX node_owner_alias_search_idx
    ON node (owner_identity_id, alias_search, id);

CREATE INDEX node_owner_transient_heard_idx
    ON node (owner_identity_id, is_saved, last_heard_at);
